inlineScript.scriptBlock:
// Get the stepper data (array of step items)
var stepperData = this.getData().items;

// Get configuration options
var showNumbers = this.getOption("showNumbers") !== false; // Default true
var showIcons = this.getOption("showIcons") !== false; // Default true
var clickable = this.getOption("clickable") || false; // Default false
var currentStep = this.getOption("currentStep") || 0; // Default 0 (first step)

this.registerEventHandlingFunction(this, "stepClicked", "index"); 


// Get the stepper container elements
var stepperContainer = this.context.element.querySelector(".stepper_maincontentbox");
var stepperList = stepperContainer.querySelector(".stepper-list");

// Clear existing stepper items
stepperList.innerHTML = "";

// Function to create a stepper item
function createStepperItem(item, index, totalItems) {
  var div = document.createElement("div");
  div.className = "stepper-item";

  // Determine step status
  var status = item.status;
  if (!status) {
    // Auto-determine status based on currentStep
    if (index < currentStep) {
      status = "completed";
    } else if (index === currentStep) {
      status = "current";
    } else {
      status = "pending";
    }
  }

  // Add status class
  div.classList.add(status);

  // Add clickable class if enabled and not disabled
  if (clickable && status !== "disabled") {
    div.classList.add("clickable");
  }

  // Create step circle
  var circle = document.createElement("div");
  circle.className = "step-circle";

  // Add icon or number to circle
  if (showIcons && status === "completed") {
    var iconDiv = document.createElement("div");
    iconDiv.className = "stepper_icon_completed";
    circle.appendChild(iconDiv);
  } else if (showIcons && status === "error") {
    var iconDiv = document.createElement("div");
    iconDiv.className = "stepper_icon_error";
    circle.appendChild(iconDiv);
  } else if (showIcons && status === "warning") {
    var iconDiv = document.createElement("div");
    iconDiv.className = "stepper_icon_warning";
    circle.appendChild(iconDiv);
  } else if (showNumbers) {
    var numberSpan = document.createElement("span");
    numberSpan.textContent = index + 1;
    circle.appendChild(numberSpan);
  }

  div.appendChild(circle);

  // Create step content container (for vertical layout)
  var contentDiv = document.createElement("div");
  contentDiv.className = "step-content";

  // Create step label
  var label = document.createElement("div");
  label.className = "step-label";
  label.textContent = item.label || item.text || "Step " + (index + 1);
  contentDiv.appendChild(label);

  // Create step description if provided
  if (item.description) {
    var description = document.createElement("div");
    description.className = "step-description";
    description.textContent = item.description;
    contentDiv.appendChild(description);
  }

  div.appendChild(contentDiv);

  // Add click event handler if clickable
  if (clickable && status !== "disabled") {
    div.addEventListener("click", function(e) {
      e.preventDefault();

      // Call custom onClick handler if provided
      if (item.onClick && typeof item.onClick === "function") {
        item.onClick(item, index);
      }

      // Fire boundary event for step change
      if (typeof me !== "undefined" && me.ui && me.ui.fireEvent) {
        me.ui.fireEvent("stepClicked", {
          step: index,
          item: item
        });
      }
    });
  }

  return div;
}

// Render stepper items
if (stepperData && Array.isArray(stepperData) && stepperData.length > 0) {
  stepperData.forEach(function(item, index) {
    var stepperItem = createStepperItem(item, index, stepperData.length);
    stepperList.appendChild(stepperItem);
  });
} else {
  // If no data, show default steps
  var defaultSteps = [
    { label: "Step 1", status: "completed" },
    { label: "Step 2", status: "current" },
    { label: "Step 3", status: "pending" }
  ];

  defaultSteps.forEach(function(item, index) {
    var stepperItem = createStepperItem(item, index, defaultSteps.length);
    stepperList.appendChild(stepperItem);
  });
}

// Made with Bob

/* Stepper Widget Styles - Carbon Design System - Vertical Layout Only */
/* Colors and typography aligned with themes/Carbon.less */

.stepper_maincontentbox {
	width: 100%;
	min-height: 80px;
	overflow: hidden;
	padding: 1rem 0;
	font-family: 'IBM Plex Sans', 'Helvetica Neue', Helvetica, Arial, sans-serif; /* @bpm-font-family-sans-serif */
}

.stepper_maincontentbox .stepper-container {
	display: table;
	width: 100%;
}

.stepper_maincontentbox .stepper-container .stepper-list {
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	position: relative;
}

/* Stepper Item */
.stepper_maincontentbox .stepper-container .stepper-list .stepper-item {
	display: flex;
	flex-direction: row;
	align-items: flex-start;
	position: relative;
	width: 100%;
	min-height: 60px;
	padding-bottom: 1rem;
}

/* Connector Line - Vertical */
.stepper_maincontentbox .stepper-container .stepper-list .stepper-item:not(:last-child)::after {
	content: '';
	position: absolute;
	top: 32px;
	left: 16px;
	width: 2px;
	height: calc(100% - 32px);
	background-color: #e0e0e0; /* Gray 20 */
	z-index: 0;
}

.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.completed:not(:last-child)::after {
	background-color: #0f62fe; /* @bpm-color-primary */
}

/* Step Circle Container */
.stepper_maincontentbox .stepper-container .stepper-list .stepper-item .step-circle {
	width: 32px;
	height: 32px;
	border-radius: 50%;
	display: flex;
	align-items: center;
	justify-content: center;
	background-color: #ffffff; /* @bpm-body-bg */
	border: 2px solid #e0e0e0; /* Gray 20 */
	position: relative;
	z-index: 1;
	transition: all 0.3s ease;
	font-size: 12px; /* @bpm-font-size-small */
	font-weight: 600; /* @bpm-font-weight-semibold */
	color: #525252; /* Gray 70 */
}

/* Step Circle - Completed */
.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.completed .step-circle {
	background-color: #0f62fe; /* @bpm-color-primary */
	border-color: #0f62fe; /* @bpm-color-primary */
	color: #ffffff; /* @bpm-text-alternate-color */
}

/* Step Circle - Current/Active */
.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.current .step-circle {
	border-color: #0f62fe; /* @bpm-color-primary */
	border-width: 3px;
	color: #0f62fe; /* @bpm-color-primary */
	box-shadow: 0 0 0 4px rgba(15, 98, 254, 0.1);
}

/* Step Circle - Error */
.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.error .step-circle {
	background-color: #da1e28; /* @bpm-color-alert */
	border-color: #da1e28; /* @bpm-color-alert */
	color: #ffffff; /* @bpm-text-alternate-color */
}

/* Step Circle - Warning */
.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.warning .step-circle {
	background-color: #f1c21b; /* Warning yellow 50 */
	border-color: #f1c21b;
	color: #161616; /* @bpm-text-color */
}

/* Step Circle - Disabled */
.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.disabled .step-circle {
	background-color: #f4f4f4; /* Gray 10 */
	border-color: #c6c6c6; /* @bpm-link-text-color-disabled */
	color: #c6c6c6; /* @bpm-link-text-color-disabled */
	cursor: not-allowed;
}

/* Step Content Container */
.stepper_maincontentbox .stepper-container .stepper-list .stepper-item .step-content {
	display: flex;
	flex-direction: column;
	flex: 1;
}

/* Step Label */
.stepper_maincontentbox .stepper-container .stepper-list .stepper-item .step-label {
	margin-top: 0;
	margin-left: 1rem;
	text-align: left;
	font-size: 12px; /* @bpm-font-size-small */
	color: #525252; /* Gray 70 */
	font-weight: 400; /* @bpm-font-weight-normal */
	max-width: none;
	word-wrap: break-word;
}

.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.current .step-label {
	color: #161616; /* @bpm-text-color */
	font-weight: 600; /* @bpm-font-weight-semibold */
}

.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.completed .step-label {
	color: #161616; /* @bpm-text-color */
}

.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.disabled .step-label {
	color: #c6c6c6; /* @bpm-link-text-color-disabled */
}

/* Step Description */
.stepper_maincontentbox .stepper-container .stepper-list .stepper-item .step-description {
	margin-top: 0.25rem;
	margin-left: 1rem;
	text-align: left;
	font-size: 10px; /* @bpm-font-size-xsmall */
	color: #8d8d8d; /* Gray 50 */
	max-width: none;
	word-wrap: break-word;
}

/* Clickable Steps */
.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.clickable {
	cursor: pointer;
}

.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.clickable:hover .step-circle {
	transform: scale(1.1);
	box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.clickable:hover .step-label {
	color: #0f62fe; /* @bpm-color-primary */
}

/* Status Icons */
.stepper_icon_completed {
	background-image: url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2216%22%20height%3D%2216%22%20viewBox%3D%220%200%2016%2016%22%3E%3Cpath%20fill%3D%22%23ffffff%22%20d%3D%22M6.5%2011.5l-3-3%201-1%202%202%205-5%201%201z%22%2F%3E%3C%2Fsvg%3E");
	width: 16px;
	height: 16px;
	background-size: 16px 16px;
	background-repeat: no-repeat;
	background-position: center;
}

.stepper_icon_error {
	background-image: url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2216%22%20height%3D%2216%22%20viewBox%3D%220%200%2016%2016%22%3E%3Cpath%20fill%3D%22%23ffffff%22%20d%3D%22M8%201C4.1%201%201%204.1%201%208s3.1%207%207%207%207-3.1%207-7-3.1-7-7-7zm3.3%209.7L8%207.4l-3.3%203.3-1.4-1.4L6.6%206%203.3%202.7l1.4-1.4L8%204.6l3.3-3.3%201.4%201.4L9.4%206l3.3%203.3-1.4%201.4z%22%2F%3E%3C%2Fsvg%3E");
	width: 16px;
	height: 16px;
	background-size: 16px 16px;
	background-repeat: no-repeat;
	background-position: center;
}

.stepper_icon_warning {
	background-image: url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2216%22%20height%3D%2216%22%20viewBox%3D%220%200%2016%2016%22%3E%3Cpath%20fill%3D%22%23161616%22%20d%3D%22M8%201L1%2015h14L8%201zm0%2010.5c-.4%200-.8-.3-.8-.8s.3-.8.8-.8.8.3.8.8-.4.8-.8.8zm.8-2.3h-1.5V5.5h1.5v3.7z%22%2F%3E%3C%2Fsvg%3E");
	width: 16px;
	height: 16px;
	background-size: 16px 16px;
	background-repeat: no-repeat;
	background-position: center;
}

/* Responsive Design */
@media (max-width: 672px) {
	.stepper_maincontentbox .stepper-container .stepper-list .stepper-item .step-label {
		font-size: 10px; /* @bpm-font-size-xsmall */
	}

	.stepper_maincontentbox .stepper-container .stepper-list .stepper-item .step-description {
		font-size: 10px; /* @bpm-font-size-xsmall */
	}

	.stepper_maincontentbox .stepper-container .stepper-list .stepper-item .step-circle {
		width: 28px;
		height: 28px;
		font-size: 10px; /* @bpm-font-size-xsmall */
	}
}

/* Animation for step transitions */
@keyframes stepPulse {
	0%, 100% {
		box-shadow: 0 0 0 4px rgba(15, 98, 254, 0.1);
	}
	50% {
		box-shadow: 0 0 0 8px rgba(15, 98, 254, 0.05);
	}
}

.stepper_maincontentbox .stepper-container .stepper-list .stepper-item.current .step-circle {
	animation: stepPulse 2s ease-in-out infinite;
}

/* Made with Bob */
